  "slots": [
    {
      "slot": 1,
      "stemPolarity": "SELECT_INCORRECT",
      "scope": "PASSAGE_WIDE",
      "concept": null,
      "answer": 3,
      "choices": [
        {
          "number": 1,
          "truth": "TRUE",
          "basis": [
            "소리는 나팔의 진동으로 바뀌고 진동의 형태를 따라서 바늘이 판에 홈을 만들어 소리를 저장한다."
          ],
          "twist": null
        },
        {
          "number": 2,
          "truth": "TRUE",
          "basis": [
            "한 파일 내의 오디오 신호에는 모든 소리 크기에 균일한 개수의 비트가 할당된다."
          ],
          "twist": null
        },
        {
          "number": 3,
          "truth": "FALSE",
          "basis": [
            "각 소리 크기에 할당되는 비트의 개수가 늘면 소리는 아날로그 원음에 가까워진다."
          ],
          "twist": {
            "label": "증감 관계 역전",
            "targetQuote": "각 소리 크기에 할당되는 비트의 개수가 늘면 소리는 아날로그 원음에 가까워진다.",
            "change": "각 소리 크기에 할당되는 비트의 개수가 늘수록 소리가 아날로그 원음에서 멀어지는 것으로 바꾼다."
          }
        },
        {
          "number": 4,
          "truth": "TRUE",
          "basis": [
            "그런데 오디오 파일은 저장하거나 네트워크를 통해 전송하기에는 데이터 양이 많다.",
            "따라서 저장 공간을 아끼고 전송이 가능하도록 오디오 신호를 압축할 필요가 있다."
          ],
          "twist": null
        },
        {
          "number": 5,
          "truth": "TRUE",
          "basis": [
            "지각부호화는 청각 특성에 따라 감도가 낮은 소리를 제거하여 오디오 신호를 압축하는 기술이다."
          ],
          "twist": null
        }
      ]
    },
    {
      "slot": 2,
      "stemPolarity": "SELECT_CORRECT",
      "scope": "PASSAGE_WIDE",
      "concept": null,
      "answer": 4,
      "choices": [
        {
          "number": 1,
          "truth": "FALSE",
          "basis": [
            "이것이 초기 녹음기의 원리인데, 소리를 아날로그 형태로 저장하였고, 이후에 등장한 매체에서도 한동안 소리를 아날로그 형태로 기록하였다."
          ],
          "twist": {
            "label": "기록 방식의 전환 시점 변경",
            "targetQuote": "이후에 등장한 매체에서도 한동안 소리를 아날로그 형태로 기록하였다.",
            "change": "초기 녹음기 이후에 등장한 매체에서는 곧바로 소리를 디지털 형태로 기록한 것으로 바꾼다."
          }
        },
        {
          "number": 2,
          "truth": "FALSE",
          "basis": [
            "일반적으로 각 소리 크기에 16비트를 할당하며, 소리 크기에 따라 16자리의 이진수 값을 달리한다."
          ],
          "twist": {
            "label": "비트 수와 이진수 값 혼동",
            "targetQuote": "소리 크기에 따라 16자리의 이진수 값을 달리한다.",
            "change": "각 소리 크기에 16비트를 할당할 때 소리 크기가 달라도 동일한 이진수 값을 사용하는 것으로 바꾼다."
          }
        },
        {
          "number": 3,
          "truth": "FALSE",
          "basis": [
            "최소가청강도는 주파수별로 그 크기가 정해져 있다.",
            "예를 들어, 1,000 Hz부터 10,000 Hz 사이에서는 아주 작은 소리도 들을 수 있지만, 100 Hz 이하의 저음에서는 훨씬 큰 소리여야 들을 수 있다."
          ],
          "twist": {
            "label": "주파수별 차이 삭제",
            "targetQuote": "최소가청강도는 주파수별로 그 크기가 정해져 있다.",
            "change": "조용할 때 소리를 감지할 수 있는 최소 크기가 주파수와 관계없이 동일한 것으로 바꾼다."
          }
        },
        {
          "number": 4,
          "truth": "TRUE",
          "basis": [
            "소리 크기와 차폐 문턱값의 차이가 큰 소리일수록 해당 소리 크기에 비트를 많이 할당하여 소리의 손실을 낮춘다."
          ],
          "twist": null
        },
        {
          "number": 5,
          "truth": "FALSE",
          "basis": [
            "지각부호화에서는 오디오 신호를 먼저 주파수에 따라 여러 개의 임계대역으로 나누고, 각 임계대역에서 최소가청강도와 차폐음을 고려하여 차폐 문턱값을 구한다."
          ],
          "twist": {
            "label": "신호 분할 기준 교체",
            "targetQuote": "오디오 신호를 먼저 주파수에 따라 여러 개의 임계대역으로 나누고",
            "change": "지각부호화에서 오디오 신호를 임계대역으로 나누는 기준을 주파수가 아니라 소리 크기로 바꾼다."
          }
        }
      ]
    },
    {
      "slot": 3,
      "stemPolarity": "SELECT_CORRECT",
      "scope": "CONCEPT",
      "concept": "차폐",
      "answer": 2,
      "choices": [
        {
          "number": 1,
          "truth": "FALSE",
          "basis": [
            "한편, 큰 소리로 인해 작은 소리가 들리지 않는 현상을 차폐라고 하며 차폐를 일으키는 큰 소리를 차폐음이라 한다."
          ],
          "twist": {
            "label": "원인음과 피차폐음 교체",
            "targetQuote": "차폐를 일으키는 큰 소리를 차폐음이라 한다.",
            "change": "차폐음이 가리키는 대상을 차폐를 일으키는 큰 소리에서 차폐로 인해 들리지 않게 된 작은 소리로 바꾼다."
          }
        },
        {
          "number": 2,
          "truth": "TRUE",
          "basis": [
            "차폐음의 주파수를 기준으로 차폐가 일어날 수 있는 가장 낮은 주파수와 가장 높은 주파수 사이의 구간을 임계대역이라고 한다."
          ],
          "twist": null
        },
        {
          "number": 3,
          "truth": "FALSE",
          "basis": [
            "두 소리의 주파수가 가까울수록 차폐가 쉽게 일어나고, 주파수가 어느 정도 차이가 나면 차폐가 일어나지 않는다."
          ],
          "twist": {
            "label": "주파수 거리와 발생 관계 역전",
            "targetQuote": "두 소리의 주파수가 가까울수록 차폐가 쉽게 일어나고",
            "change": "두 소리의 주파수가 가까울수록 차폐가 쉽게 일어나는 관계를 주파수가 멀어질수록 쉽게 일어나는 관계로 바꾼다."
          }
        },
        {
          "number": 4,
          "truth": "FALSE",
          "basis": [
            "임계대역의 폭은 차폐음의 주파수에 따라 다른데 고음에서는 저음에서보다 임계대역이 훨씬 넓다."
          ],
          "twist": {
            "label": "대역 폭의 비교 역전",
            "targetQuote": "고음에서는 저음에서보다 임계대역이 훨씬 넓다.",
            "change": "차폐음이 고음일 때의 임계대역이 저음일 때보다 좁은 것으로 바꾼다."
          }
        },
        {
          "number": 5,
          "truth": "FALSE",
          "basis": [
            "차폐를 고려한, 실제 청각이 감지할 수 있는 소리 크기의 최솟값을 차폐 문턱값이라 한다."
          ],
          "twist": {
            "label": "경계값의 성격 교체",
            "targetQuote": "실제 청각이 감지할 수 있는 소리 크기의 최솟값",
            "change": "차폐 문턱값을 차폐를 고려하여 실제 청각이 감지할 수 있는 소리 크기의 최댓값으로 바꾼다."
          }
        }
      ]
    }
  ]
}

